/// A node in a decoded source file, tagged with what the schema says it is.
///
/// A struct over the blob and an index, so it is the same two words a raw `int` walk
/// carries plus the blob it was already holding. The tag is erased at runtime.
[<Struct; NoEquality; NoComparison>]
type Node<'Tag when 'Tag :> AnyNode> =
    internal { File: Ast.SourceFile; Index: int }

    /// The node's kind, read from the blob. Tags are erased, so this is the only thing that
    /// knows what the node actually is.
    member this.Kind = Ast.kind this.File this.Index

    /// Start of the node including leading trivia, in UTF-16 code units.
    member this.Pos = Ast.pos this.File this.Index

    /// End of the node, in UTF-16 code units.
    member this.End = Ast.endPos this.File this.Index

    /// The node's text, cooked rather than as spelled, for the kinds that carry any.
    member this.Text = Ast.text this.File this.Index

/// The escape hatch, and the operations that hold for every node whatever its tag.
[<RequireQualifiedAccess>]
module Node =

    /// Tags a raw node index. The index is not checked against the tag - `ofIndex` is the
    /// door back in from a raw walk, and the caller is asserting what it found.
    let ofIndex<'Tag when 'Tag :> AnyNode> (file: Ast.SourceFile) (index: int) : Node<'Tag> =
        { File = file; Index = index }

    /// The raw node index, for dropping down to `Ast` and `AstNode`.
    let index (node: Node<'Tag>) = node.Index

    /// The decoded file the node belongs to.
    let file (node: Node<'Tag>) = node.File

    /// Re-tags a node without checking it. The generated views and widenings are the intended
    /// callers; it cannot produce an invalid node, only a wrong claim about one.
    let retag<'From, 'To when 'From :> AnyNode and 'To :> AnyNode> (node: Node<'From>) : Node<'To> =
        { File = node.File; Index = node.Index }

    /// The file's root node.
    let root (file: Ast.SourceFile) : Node<SourceFile> = { File = file; Index = Ast.Root }

    /// True when both refer to the same node of the same file, whatever their tags.
    let sameAs (other: Node<'Other>) (node: Node<'Tag>) =
        node.Index = other.Index && obj.ReferenceEquals(node.File.Data, other.File.Data)

    /// The node's parent, or `ValueNone` at the root.
    let parent (node: Node<'Tag>) : Node<AnyNode> voption =
        match Ast.parent node.File node.Index with
        | 0 -> ValueNone
        | index -> ValueSome { File = node.File; Index = index }

    /// The node's direct children, in blob order, untagged.
    let children (node: Node<'Tag>) : Node<AnyNode> seq =
        Ast.children node.File node.Index |> Seq.map (fun index -> { File = node.File; Index = index })

    /// Every node under this one, untagged. Narrow with a view.
    let descendants (node: Node<'Tag>) : Node<AnyNode> seq =
        Ast.descendants node.File node.Index |> Seq.map (fun index -> { File = node.File; Index = index })

/// Widening, one module per alias. Each is the identity at runtime; the point is that
/// the constraint only admits tags the schema says belong to the alias.
[<AutoOpen>]
module Widenings =

    /// Widens any `Expression` to `Node<Expression>`.
    [<RequireQualifiedAccess; CompilationRepresentation(CompilationRepresentationFlags.ModuleSuffix)>]
    module Expression =

        let inline ofNode<'Tag when 'Tag :> Expression> (node: Node<'Tag>) : Node<Expression> =
            Node.retag node

    /// Widens any `Statement` to `Node<Statement>`.
    [<RequireQualifiedAccess; CompilationRepresentation(CompilationRepresentationFlags.ModuleSuffix)>]
    module Statement =

        let inline ofNode<'Tag when 'Tag :> Statement> (node: Node<'Tag>) : Node<Statement> =
            Node.retag node

    /// Widens any `TypeNode` to `Node<TypeNode>`.
    [<RequireQualifiedAccess; CompilationRepresentation(CompilationRepresentationFlags.ModuleSuffix)>]
